<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute,useRouter,RouterLink } from 'vue-router'
import { assetUrl,useLearningStore } from '../api'
const route=useRoute(),router=useRouter(),api=useLearningStore()
const lesson=ref(null),error=ref(''),loading=ref(true),starting=ref(false),pageIndex=ref(0),selectedWord=ref(null)
async function load(){loading.value=true;error.value='';try{lesson.value=await api.request(`novel-lessons/${encodeURIComponent(route.params.id)}`);pageIndex.value=0}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load);watch(()=>route.params.id,load)
const page=computed(()=>lesson.value?.pages?.[pageIndex.value]||{})
async function start(){starting.value=true;error.value='';try{const s=await api.startFun(lesson.value.paperId);router.push(`/sessions/${s.id}`)}catch(e){error.value=e.message}finally{starting.value=false}}
</script>
<template><div class="content-page detail-page"><RouterLink class="back-dark" to="/novel">← 返回趣味阅读</RouterLink><div v-if="loading" class="state-box">正在读取章节…</div><div v-else-if="error" class="state-box error">{{error}} <button @click="load">重试</button></div><template v-else><div class="section-top"><p class="eyebrow">STORY / {{lesson.category}}</p><span>{{lesson.questionCount}} 道练习</span></div><h2>{{lesson.title}}</h2><p class="page-lead">{{lesson.note}}</p><div class="detail-actions"><button class="primary-action" :disabled="!lesson.published||starting" @click="start">{{starting?'正在准备…':'开始本篇练习 ↗'}}</button><a class="secondary-action" :href="`${assetUrl(lesson.material?.fileUrl)}#page=${page.number||lesson.startPage}`" target="_blank" rel="noopener">查看原 PDF</a></div><details class="vocab-panel"><summary>本篇词卡（{{lesson.vocabulary?.length||0}}）<span>先阅读，再展开回顾</span></summary><div class="vocab-grid"><article v-for="(v,i) in lesson.vocabulary||[]" :key="i"><strong>{{v.word}}</strong><p>{{v.meaning||'原文记忆词'}} · 第 {{v.sourcePage}} 页</p><small>{{v.excerpt}}</small></article></div></details><div class="reader-toolbar"><button :disabled="pageIndex===0" @click="pageIndex--;selectedWord=null">← 上一页</button><select v-model.number="pageIndex" aria-label="选择页码"><option v-for="(p,i) in lesson.pages||[]" :key="i" :value="i">第 {{p.number}} 页{{p.recall?' · 回忆版':''}}</option></select><button :disabled="pageIndex>=lesson.pages.length-1" @click="pageIndex++;selectedWord=null">下一页 →</button></div><article class="reader-page"><div class="reader-label">{{page.recall?'背诵回忆版':'原文阅读'}} · 第 {{page.number}} 页</div><img v-if="page.imageUrl" class="page-image" :src="assetUrl(page.imageUrl)" :alt="`原文第 ${page.number} 页`"><template v-if="page.readingTokens?.length"><p class="reader-hint">假名标在词语上方，点击词语查看中文释义。</p><div class="annotated-text"><template v-for="(token,i) in page.readingTokens" :key="i"><button v-if="token.word" class="ruby-word" :class="{selected:selectedWord===i}" :aria-label="`${token.word}，读音 ${token.reading}，点击查看释义`" @click="selectedWord=selectedWord===i?null:i"><ruby>{{token.word}}<rt>{{token.reading}}</rt></ruby><span v-if="selectedWord===i" class="word-popover">{{token.meaning}}</span></button><span v-else>{{token.text}}</span></template></div></template><details v-else-if="page.imageUrl"><summary>展开可复制文本</summary><p class="reading-text">{{page.text}}</p></details><p v-else class="reading-text">{{page.text}}</p></article><p class="source-caption">出处：{{lesson.material?.filename}} · 第 {{page.number}} 页<br>原文件校验值：{{lesson.material?.sha256}}</p></template></div></template>
